challenge('original error is unchanged and a caller rethrow still propagates the same object', () => {
  const d = createCheckoutFailureDiagnostics(), original = new Error(canary);
  const priorMessage = original.message, priorStack = original.stack;
  let propagated;
  try {
    d.recordFailure(original, 'test', 'testing-form', { pathname: '/checkout' });
    throw original; // Required integration pattern; recording is never a fail handler.
  } catch (error) { propagated = error; }
  check(propagated === original);
  check(original.message === priorMessage && original.stack === priorStack);
  check(!JSON.stringify(d.snapshot()).includes(canary));
});

